      sum += r[k-i-1]*cur[i];
    }

    alpha = - (r[k] + sum)/beta;

    #pragma omp parallel for simd default(none) shared(k, alpha, cur, next) schedule(static) if(k > 64)
    for (i = 0; i < k; i++) {
      next[i] = cur[i] + alpha*cur[k-i-1];
    }
    next[k] = alpha;

    tmp = cur;
    cur = next;
    next = tmp;
  }
}
#pragma endscop

